import { VOCAB } from "@/lib/vocab";

/**
 * The public developer docs, as data. One source for two views: app/docs/page.tsx (the pixel page)
 * and docs/API.md (generated by scripts/gen-api-md.ts, checked by lib/docs/content.test.ts).
 * Role words come from VOCAB so the rename flows through. Inline `code` uses backticks.
 */

export type DocBlock =
  | { kind: "p"; text: string }
  | { kind: "list"; items: string[] }
  | { kind: "steps"; items: string[] }
  | { kind: "code"; lang?: string; text: string }
  | { kind: "table"; head: string[]; rows: string[][] }
  | { kind: "note"; tone: "warn" | "safe"; text: string };

export type DocSection = { id: string; tag: string; title: string; blocks: DocBlock[] };

const guard = VOCAB.guard.toLowerCase();
const vault = VOCAB.vault.toLowerCase();
const op = VOCAB.op.toLowerCase();
const owner = VOCAB.owner.toLowerCase();
const operator = VOCAB.operator.toLowerCase();

